#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <bitset>
#include <tuple>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;

    vector<string> nau(n), pom(n);
    for (int i = 0; i < n; ++i) cin >> nau[i];
    for (int i = 0; i < n; ++i) cin >> pom[i];

    vector<vector<int>> odl(n, vector<int>(n, 1000));
    int sx = -1, sy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] == 'Z') tie(sx, sy) = {i, j};

    const int dx[] = {-1, 0, 1, 0, 0};
    const int dy[] = {0, 1, 0, -1, 0};
    auto inside = [n](int x, int y) { return x >= 0 && x < n && y >= 0 && y < n; };
    auto is_digit = [](char c) { return c >= '0' && c <= '9'; };

    queue<pair<int,int>> q;
    odl[sx][sy] = 0;
    q.emplace(sx, sy);
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (inside(nx, ny) && is_digit(nau[nx][ny]) && odl[nx][ny] == 1000) {
                odl[nx][ny] = odl[x][y] + 1;
                q.emplace(nx, ny);
            }
        }
    }

    // Flatten 5D index: [k][i][j][l][m] -> index = ((k*10 + i)*10 + j)*10 + l)*10 + m
    const int K = 60, D = 10;
    const int total = K * D * D * D * D;
    vector<bool> moge(total, false);

    auto idx = [&](int k, int i, int j, int l, int m) {
        return ((((k * D + i) * D + j) * D + l) * D + m);
    };

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int d = 0; d < 5; ++d) {
                int ni = i + dx[d], nj = j + dy[d];
                if (inside(ni, nj) && is_digit(nau[i][j]) && is_digit(nau[ni][nj]))
                    moge[idx(0, i, j, ni, nj)] = true;
            }

    for (int k = 0; k <= t - 2; ++k)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int l = 0; l < n; ++l)
                    for (int m = 0; m < n; ++m) {
                        if (!moge[idx(k, i, j, l, m)]) continue;
                        for (int d = 0; d < 5; ++d) {
                            int nl = l + dx[d], nm = m + dy[d];
                            if (inside(nl, nm) && is_digit(nau[nl][nm]) && odl[l][m] >= k+2 && odl[nl][nm] >= k+2)
                                moge[idx(k+1, i, j, nl, nm)] = true;
                        }
                    }

    vector<pair<int,int>> a;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (is_digit(nau[i][j]))
                a.emplace_back(i, j);

    int V = 2 * (int)a.size() + 2;
    vector<vector<pair<int,int>>> G(V);

    for (int i = 0; i < (int)a.size(); ++i) {
        int cap1 = nau[a[i].first][a[i].second] - '0';
        G[0].emplace_back(i+1, cap1);
        G[i+1].emplace_back(0, 0);
        int cap2 = pom[a[i].first][a[i].second] - '0';
        G[a.size()+1+i].emplace_back(V-1, cap2);
        G[V-1].emplace_back(a.size()+1+i, 0);
    }

    for (int i = 0; i < (int)a.size(); ++i)
        for (int j = 0; j < (int)a.size(); ++j) {
            bool reach = false;
            for (int k = 0; k <= t-1; ++k) {
                if (moge[idx(k, a[i].first, a[i].second, a[j].first, a[j].second)]) {
                    reach = true;
                    break;
                }
            }
            if (reach) {
                G[i+1].emplace_back(a.size()+1+j, 1000);
                G[a.size()+1+j].emplace_back(i+1, 0);
            }
        }

    int flow = 0;
    while (true) {
        vector<bool> vis(V, false);
        vector<int> par(V, -1);
        queue<int> q2;
        vis[0] = true;
        q2.push(0);
        while (!q2.empty()) {
            int u = q2.front(); q2.pop();
            for (auto& e : G[u]) {
                if (!vis[e.first] && e.second > 0) {
                    vis[e.first] = true;
                    par[e.first] = u;
                    q2.push(e.first);
                }
            }
        }
        if (par[V-1] == -1) break;

        int add = 1000;
        for (int v = V-1; v != 0; v = par[v]) {
            int u = par[v];
            for (auto& e : G[u])
                if (e.first == v) add = min(add, e.second);
        }

        for (int v = V-1; v != 0; v = par[v]) {
            int u = par[v];
            for (auto& e : G[u])
                if (e.first == v) e.second -= add;
            for (auto& e : G[v])
                if (e.first == u) e.second += add;
        }
        flow += add;
    }

    cout << flow;
    return 0;
}
